\echo email-daily before 1
EXPLAIN (ANALYZE, BUFFERS, FORMAT TEXT) WITH RECURSIVE log_origin AS (
 SELECT s.id, s.id AS cur, s.parent_log_id, s.trigger_type, s.sent_at, s.open_tracked, s.status, COALESCE(tl.name, apl.name, et.name) AS campaign, p.name AS product, 0 AS depth
 FROM email_send_logs s LEFT JOIN email_template_links tl ON tl.id = s.template_link_id LEFT JOIN email_auto_personalized_links apl ON apl.id = s.auto_personalized_link_id LEFT JOIN email_templates et ON et.id = s.email_template_id LEFT JOIN products p ON p.id = apl.product_id
 WHERE s.org_id='00000000-0000-4000-8000-0000000000a9' AND s.sent_at >= now()-interval '90 days' AND s.sent_at <= now()
 UNION ALL
 SELECT lo.id, par.id, par.parent_log_id, lo.trigger_type, lo.sent_at, lo.open_tracked, lo.status, COALESCE(tl.name, apl.name, et.name), p.name, lo.depth + 1
 FROM log_origin lo JOIN email_send_logs par ON par.id = lo.parent_log_id LEFT JOIN email_template_links tl ON tl.id = par.template_link_id LEFT JOIN email_auto_personalized_links apl ON apl.id = par.auto_personalized_link_id LEFT JOIN email_templates et ON et.id = par.email_template_id LEFT JOIN products p ON p.id = apl.product_id
 WHERE lo.campaign IS NULL AND lo.depth < 10),
resolved AS (SELECT DISTINCT ON (id) id, campaign, product, trigger_type, sent_at, open_tracked, status FROM log_origin WHERE campaign IS NOT NULL ORDER BY id, depth ASC),
final AS (SELECT lo.id, NULL::text AS campaign, NULL::text AS product, lo.trigger_type, lo.sent_at, lo.open_tracked, lo.status FROM log_origin lo WHERE lo.depth = 0 AND lo.id NOT IN (SELECT id FROM resolved) UNION ALL SELECT id, campaign, product, trigger_type, sent_at, open_tracked, status FROM resolved)
SELECT (f.sent_at AT TIME ZONE 'Asia/Seoul')::date::text, f.trigger_type, COALESCE(f.product,''), COALESCE(f.campaign,''), count(*)::int,
  count(*) FILTER (WHERE EXISTS (SELECT 1 FROM email_click_logs ecl WHERE ecl.send_log_id = f.id AND ecl.is_bot = false))::int
FROM final f GROUP BY 1,2,3,4 ORDER BY 1 DESC, 5 DESC;
